head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#fffaf0" value="#fffaf0"/><Variable name="page.text" description="Text color" type="color" default="#253051" value="#253051"/><Variable name="theme.accent" description="Accent color" type="color" default="#663ea5" value="#663ea5"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:'Fredoka', Trebuchet MS, sans-serif;--body:Verdana, sans-serif}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
a{color:inherit}a:focus-visible,summary:focus-visible{outline:3px solid currentColor;outline-offset:5px}img{max-width:100%;height:auto}svg{display:block;width:100%;height:auto} .post-title a{text-decoration:none}.post-meta{font-size:.75rem;text-transform:uppercase;letter-spacing:.12em}.post-excerpt{line-height:1.7}.post-media{overflow:hidden}.post-card{min-width:0}.post-card a:hover{text-decoration:underline}.post-card:hover .post-media{filter:saturate(1.15)}.post-media img{transition:transform .4s}.post-card:hover .post-media img{transform:scale(1.035)}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}body{margin:0;background:#fffaf0;color:#253051;font-family:Verdana,sans-serif}.why-nav{padding:25px 5%;display:flex;justify-content:space-between;align-items:center}.why-nav .brand{font:bold 27px "Trebuchet MS",sans-serif;text-decoration:none;letter-spacing:-1px}.why-nav .brand b{color:#663ea5}.why-nav nav{display:flex;gap:28px;font-size:12px;font-weight:bold}.why-nav nav a{text-decoration:none}.why-hero{display:grid;grid-template-columns:1fr 1fr;align-items:center;gap:40px;padding:45px 5% 80px}.why-pill{display:inline-block;font-size:9px;font-weight:bold;letter-spacing:.08em;background:#ffe899;padding:10px 14px;border-radius:30px}.why-hero h1{font:bold clamp(44px,6.4vw,86px)/1.02 "Trebuchet MS",sans-serif;letter-spacing:-.06em;margin:25px 0}.why-hero h1 em{font-style:normal;color:#663ea5}.why-hero p{font-size:13px;line-height:1.9;max-width:390px}.why-button{display:inline-flex;align-items:center;gap:30px;background:#663ea5;color:#fff;padding:18px 25px;border-radius:50px;font-size:13px;font-weight:bold;text-decoration:none;margin-top:20px;box-shadow:0 5px 0 #422871}.why-button:hover{transform:translateY(-2px)}.why-button span{font-size:22px}.why-art{position:relative;transform:rotate(3deg)}.why-art svg{border:3px solid #253051;border-radius:42px}.why-bubble{position:absolute;bottom:-23px;left:-25px;background:#ffb7bf;border:3px solid #253051;transform:rotate(-12deg);padding:24px 28px;border-radius:50%;font:17px/1.35 "Trebuchet MS",sans-serif}.why-explore{padding:45px 5% 55px;background:#e6e0f7;border-top:3px solid #253051;border-bottom:3px solid #253051}.why-heading{display:flex;align-items:center;justify-content:center;gap:30px}.why-heading>span{font-size:35px;color:#663ea5}.why-heading h2{font:bold 33px "Trebuchet MS",sans-serif;letter-spacing:-1px;text-align:center}.why-islands{display:grid;grid-template-columns:repeat(3,1fr);gap:25px;margin-top:30px}.why-islands a{padding:30px 25px;background:#fffaf0;border:2px solid #253051;border-radius:26px;text-decoration:none;box-shadow:4px 5px 0 #253051;transition:transform .2s}.why-islands a:hover{transform:rotate(-2deg)}.why-islands a:nth-child(2){background:#d8efcd}.why-islands a:nth-child(3){background:#ffe899}.why-island-icon{display:block;font:bold 55px "Trebuchet MS",sans-serif;line-height:1;margin-bottom:20px;color:#663ea5}.why-islands strong{font:bold 23px "Trebuchet MS",sans-serif}.why-islands p{font-size:11px;line-height:1.8}.why-islands b{display:block;font-size:9px;margin-top:25px;letter-spacing:.08em}.why-wonder{padding:55px 10%;display:flex;gap:70px;align-items:center}.why-wonder-symbol{font:bold 190px "Trebuchet MS",sans-serif;color:#ef9572;transform:rotate(-10deg);line-height:1}.why-wonder h2{font:bold 34px/1.1 "Trebuchet MS",sans-serif;letter-spacing:-1px}.why-wonder details{background:#e6e0f7;border:2px solid;border-radius:14px;padding:16px 20px;max-width:580px}.why-wonder summary{cursor:pointer;font-size:12px;font-weight:bold}.why-wonder details p{font-size:12px;line-height:1.8}.section-heading{font:bold 34px "Trebuchet MS",sans-serif;margin:25px 5%;letter-spacing:-1px}.posts-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:25px;padding:0 5% 65px}.post-card{border:2px solid;border-radius:20px;padding:16px;background:#fff}.post-media{aspect-ratio:1.5;border-radius:12px;background:#a9dcf6;margin-bottom:18px}.post-meta{color:#663ea5;font-size:9px}.post-title{font:bold 24px/1.12 "Trebuchet MS",sans-serif;letter-spacing:-.5px}.post-excerpt{font-size:11px}.why-promise{padding:45px 20px;text-align:center;background:#ffe899;border-top:3px solid;border-bottom:3px solid}.why-promise>span{font-size:40px;color:#663ea5}.why-promise h2{font:bold 35px/1.15 "Trebuchet MS",sans-serif;letter-spacing:-1px}.why-promise p{font-size:12px}.why-promise a{display:inline-block;font-size:10px;font-weight:bold;margin:18px}.why-footer{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:30px 5%}.why-footer strong{font:bold 24px "Trebuchet MS",sans-serif;color:#663ea5}.why-footer span{font-size:10px;line-height:1.7}.why-footer a{font-size:10px}@media(max-width:700px){.why-nav .brand{font-size:23px}.why-nav nav{gap:13px;font-size:10px}.why-hero{grid-template-columns:1fr;padding-top:25px}.why-hero h1{font-size:62px}.why-art{margin:15px}.why-islands,.posts-grid{grid-template-columns:1fr}.why-heading>span{display:none}.why-heading h2{font-size:28px}.why-wonder{padding:40px 5%;gap:20px}.why-wonder-symbol{font-size:90px}.why-wonder h2{font-size:26px}.why-promise h2{font-size:29px}.why-footer{flex-wrap:wrap}} .latest{max-width:none;margin:0;padding:0}
h1,h2,h3{font-family:'Fredoka', Trebuchet MS, sans-serif}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
